host.example:
variant WindowSize {
  case compact
  case medium
  case expanded
}

variant AppSurface {
  case mobile
  case watch
  case web
}

host Default(
  sizeClass: WindowSize = .medium,
  surface: AppSurface = .mobile,
  previewBackground: Color = #F4F4F5
) mount {
  let width: Distance =
    host["view.width"] as? Distance
    ?? 800
  if width < 600 {
    self.sizeClass = .compact
  }
}

component Shell <Host>() layout {
  if sizeClass == .compact {
    direction = .column
  } else {
    direction = .row
  }
  children = []
}

