component SearchField <EditableText>(
  placeholder: String = "Search"
) text {
  content = placeholder
  if isEditing {
    content = self.value
  } else if !isEmpty {
    content = self.value
  }
  self.editingFinished = {
    finishEditing()
    emit change(value)
  }
} emits {
  change(value: String)
}

